from fractions import Fraction as F
import json
from itertools import product

c = F(20, -24) - (2 + F(-3))
# f(x) = 1/16 x^4 + 1/8 x^2 + 0 x + 1 - c x^3 ; coefficients low->high
f = [F(1), F(0), F(1, 8), -c, F(1, 16)]
k = [f[i] * i for i in range(1, len(f))]  # derivative, low->high

def ev(p, x):
    return sum(a * x**i for i, a in enumerate(p))

def divide_root(p, r):
    # synthetic division of poly (low->high) by (x - r)
    hi = p[::-1]
    out = [hi[0]]
    for a in hi[1:]:
        out.append(a + out[-1] * r)
    rem = out.pop()
    return out[::-1], rem

lead = k[-1]
p = k[:]
cands = sorted({F(a, b) for a, b in product(range(-12, 13), range(1, 13))})
roots = {}
changed = True
while len(p) > 1 and changed:
    changed = False
    for r in cands:
        if ev(p, r) == 0:
            q, rem = divide_root(p, r)
            if rem == 0:
                roots[r] = roots.get(r, 0) + 1
                p = q
                changed = True
                break

def fmt_root(r):
    if r == 0:
        return "x"
    return f"(x - {r})" if r > 0 else f"(x + {-r})"

parts = []
for r in sorted(roots):
    s = fmt_root(r)
    if roots[r] > 1:
        s += f"**{roots[r]}"
    parts.append(s)
remaining = p  # constant if fully factored
const = remaining[0] if len(remaining) == 1 else None
if const is None:
    ans = "UNSUPPORTED"
else:
    body = "*".join(parts)
    if const == 1:
        ans = body
    elif const.numerator == 1:
        ans = f"{body}/{const.denominator}"
    else:
        ans = f"{const}*{body}"
print(json.dumps({"final_answer": ans, "evidence": {"c": str(c), "k_coeffs_low_to_high": [str(a) for a in k], "roots": {str(r): m for r, m in roots.items()}, "leading": str(lead)}}))
